import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Class: BossBuilder","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/classes/BossBuilder.md","filePath":"api/twine/classes/BossBuilder.md"}'),s={name:"api/twine/classes/BossBuilder.md"};function n(i,e,d,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">twine</a> / BossBuilder</p><h1 id="class-bossbuilder" tabindex="-1">Class: BossBuilder <a class="header-anchor" href="#class-bossbuilder" aria-label="Permalink to &quot;Class: BossBuilder&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L111" target="_blank" rel="noreferrer">boss.ts:111</a></p><p>Fluent builder for a <strong>boss fight</strong>: a real mob, staged by health percentage, attacking out of a weighted pool of cooldown-gated abilities, with a bar bound to whoever is in the arena. <code>toModule(name)</code> turns it into a drop-in <a href="./../interfaces/ConfiguredModule.html">ConfiguredModule</a> listed in a parent module&#39;s <code>imports</code>.</p><p>const king = defineBoss(Wither({ customName: &quot;Bone King&quot; }), Pos(0, 70, 0)) .arena({ kind: &quot;region&quot;, center: [0, 70, 0], radius: 30 }) .bossbar(Component(&quot;Bone King&quot;), &quot;purple&quot;) .phase(&quot;one&quot;) .ability(&quot;slam&quot;, { cooldown: 60, weight: 3, body: (ctx) =&gt; ... }) .phase(&quot;two&quot;, { at: 50, bar: { color: &quot;red&quot;, name: Component(&quot;Enraged&quot;) } }) .ability(&quot;beam&quot;, { cooldown: 40, body: (ctx) =&gt; ... }) .onVictory((ctx) =&gt; ctx.loot().giveLoot(Selector.self(), reward));</p><p>@Module({ name: &quot;keep&quot;, imports: [king.toModule(&quot;bone_king&quot;)] })</p><p>The arena is an ordinary <code>area</code> trigger, so entering the zone starts the fight and the region emptying (everyone left, or everyone died and respawned outside) is the loss condition - no separate arena concept, and &quot;everyone dead = fail&quot; costs no code.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new BossBuilder</strong>(<code>nbt</code>, <code>spawn</code>): <code>BossBuilder</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L118" target="_blank" rel="noreferrer">boss.ts:118</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="nbt" tabindex="-1">nbt <a class="header-anchor" href="#nbt" aria-label="Permalink to &quot;nbt&quot;">​</a></h5><p><code>IdentifiedEntityNbt</code></p><h5 id="spawn" tabindex="-1">spawn <a class="header-anchor" href="#spawn" aria-label="Permalink to &quot;spawn&quot;">​</a></h5><p><code>PosValue</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>BossBuilder</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="ability" tabindex="-1">ability() <a class="header-anchor" href="#ability" aria-label="Permalink to &quot;ability()&quot;">​</a></h3><blockquote><p><strong>ability</strong>(<code>name</code>, <code>opts</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L152" target="_blank" rel="noreferrer">boss.ts:152</a></p><p>Attach an ability to the <strong>most recently declared phase</strong>. To use the same attack in two phases, declare it in both off a shared <code>body</code> - a name registry would buy nothing but a string back-reference.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h5 id="opts" tabindex="-1">opts <a class="header-anchor" href="#opts" aria-label="Permalink to &quot;opts&quot;">​</a></h5><p><a href="./../interfaces/AbilityOpts.html"><code>AbilityOpts</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="arena" tabindex="-1">arena() <a class="header-anchor" href="#arena" aria-label="Permalink to &quot;arena()&quot;">​</a></h3><blockquote><p><strong>arena</strong>(<code>trigger</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L124" target="_blank" rel="noreferrer">boss.ts:124</a></p><p>Where the fight happens - the same <a href="./../type-aliases/AreaTrigger.html">AreaTrigger</a> any area module takes.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="trigger" tabindex="-1">trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;trigger&quot;">​</a></h5><p><a href="./../type-aliases/AreaTrigger.html"><code>AreaTrigger</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="bossbar" tabindex="-1">bossbar() <a class="header-anchor" href="#bossbar" aria-label="Permalink to &quot;bossbar()&quot;">​</a></h3><blockquote><p><strong>bossbar</strong>(<code>name</code>, <code>color?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L130" target="_blank" rel="noreferrer">boss.ts:130</a></p><p>Show a bar while the fight runs, tracking the boss&#39;s health.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>ComponentValue</code></p><h5 id="color" tabindex="-1">color? <a class="header-anchor" href="#color" aria-label="Permalink to &quot;color?&quot;">​</a></h5><p><a href="./../type-aliases/BossbarColor.html"><code>BossbarColor</code></a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="ondefeat" tabindex="-1">onDefeat() <a class="header-anchor" href="#ondefeat" aria-label="Permalink to &quot;onDefeat()&quot;">​</a></h3><blockquote><p><strong>onDefeat</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L169" target="_blank" rel="noreferrer">boss.ts:169</a></p><p>The arena emptied with the boss still alive. Runs as each participant.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/BossBody.html"><code>BossBody</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="onvictory" tabindex="-1">onVictory() <a class="header-anchor" href="#onvictory" aria-label="Permalink to &quot;onVictory()&quot;">​</a></h3><blockquote><p><strong>onVictory</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L163" target="_blank" rel="noreferrer">boss.ts:163</a></p><p>The boss died. Runs <strong>as each participant</strong>, so <code>@s</code> is a player to reward.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body-1" tabindex="-1">body <a class="header-anchor" href="#body-1" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/BossBody.html"><code>BossBody</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="phase" tabindex="-1">phase() <a class="header-anchor" href="#phase" aria-label="Permalink to &quot;phase()&quot;">​</a></h3><blockquote><p><strong>phase</strong>(<code>label</code>, <code>opts?</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L136" target="_blank" rel="noreferrer">boss.ts:136</a></p><p>Declare a phase. The <strong>first</strong> one declared is where the fight starts.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="label" tabindex="-1">label <a class="header-anchor" href="#label" aria-label="Permalink to &quot;label&quot;">​</a></h5><p><code>string</code></p><h5 id="opts-1" tabindex="-1">opts? <a class="header-anchor" href="#opts-1" aria-label="Permalink to &quot;opts?&quot;">​</a></h5><p><a href="./../interfaces/PhaseOpts.html"><code>PhaseOpts</code></a> = <code>{}</code></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="tomodule" tabindex="-1">toModule() <a class="header-anchor" href="#tomodule" aria-label="Permalink to &quot;toModule()&quot;">​</a></h3><blockquote><p><strong>toModule</strong>(<code>name</code>, <code>opts?</code>): <a href="./../interfaces/ConfiguredModule.html"><code>ConfiguredModule</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/3f0317adfc9e342144a70bee08f595c13cea2c69/twine/src/boss.ts#L175" target="_blank" rel="noreferrer">boss.ts:175</a></p><p>Compile to a drop-in <a href="./../interfaces/ConfiguredModule.html">ConfiguredModule</a> (name = module / objective / tag id).</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h5 id="opts-2" tabindex="-1">opts? <a class="header-anchor" href="#opts-2" aria-label="Permalink to &quot;opts?&quot;">​</a></h5><p><a href="./../interfaces/BossModuleOpts.html"><code>BossModuleOpts</code></a> = <code>{}</code></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/ConfiguredModule.html"><code>ConfiguredModule</code></a></p>',96)])])}const p=a(s,[["render",n]]);export{b as __pageData,p as default};
